/* DWARF original prototype: void UsePacketEncode(CItem * this, LPCHARACTER ch, LPCHARACTER victim,
   packet_item_use * packet) */

void __thiscall
CItem::UsePacketEncode(CItem *this,LPCHARACTER ch,LPCHARACTER victim,packet_item_use *packet)

{
  if (this->m_pProto->dwVnum != 0) {
    packet->header = '\x16';
    packet->ch_vid = (ch->m_vid).m_id;
    packet->victim_vid = (victim->m_vid).m_id;
    packet->pos = this->m_bCell;
    packet->vnum = this->m_pProto->dwVnum;
  }
  return;
}
